'use strict';
(() => {
 const body=document.body, asset=body.dataset.assets, isStatic=body.dataset.static==='true';
 const $=id=>document.getElementById(id);
 const read=id=>$(id)?JSON.parse($(id).textContent):null;
 const locations=read('locations-data')||[];
 const normalize=s=>s.toLowerCase().normalize('NFD').replace(/\p{M}/gu,'').trim().replace(/^(?:град\s+|гр\.\s*|село\s+|с\.\s*)/u,'').trim();
 const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
 function makeMap(id){if(!$(id))return null;if(!window.L){$(id).append(node('p','The map could not load. Your saved places are still listed below.','map-unavailable'));return null;}const m=L.map(id,{preferCanvas:true}).setView([42.7,25.2],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(m);return m;}
 function popup(loc){const e=node('div');e.append(node('h3',loc.name_bg),node('p',loc.category));if(loc.sto_nto)e.append(node('span','100 НТО','badge'));return e;}
 function pin(loc,layer){const national=Boolean(loc.sto_nto),size=national?28:24;const icon=L.divIcon({className:'atlas-pin-icon',html:national?'<span class="atlas-pin atlas-pin-national" aria-hidden="true">★</span>':'<span class="atlas-pin atlas-pin-regular" aria-hidden="true"><span class="atlas-pin-dot"></span></span>',iconSize:[size,size],iconAnchor:[size/2,size/2],popupAnchor:[0,-size/2]});return L.marker([loc.latitude,loc.longitude],{icon,alt:loc.name_bg,title:loc.name_bg+(national?' · 100 НТО':''),keyboard:true,riseOnHover:true}).bindPopup(popup(loc)).addTo(layer);} 
 function card(loc,onMap){const e=node('article',undefined,'place-card');e.append(node('span',loc.category,'category-label'),node('h3',loc.name_bg));const bottom=node('div',undefined,'card-bottom');bottom.append(loc.sto_nto?node('span','100 НТО','badge'):node('span','Saved place','small muted'));if(loc.distance_km!==undefined)bottom.append(node('strong',loc.distance_km.toFixed(2)+' km'));else if(onMap){const b=node('button','View on map ↗','pin-button');b.type='button';b.addEventListener('click',()=>onMap(loc));bottom.append(b);}e.append(bottom);return e;}
 function distance(a,b){const r=Math.PI/180,dp=(b.latitude-a.lat)*r,dl=(b.longitude-a.lon)*r;const v=Math.sin(dp/2)**2+Math.cos(a.lat*r)*Math.cos(b.latitude*r)*Math.sin(dl/2)**2;return 6371.0088*2*Math.asin(Math.sqrt(Math.min(1,Math.max(0,v))));}
 if(body.dataset.page==='index'){
  const map=makeMap('map'), pins=map?L.layerGroup().addTo(map):null;const routeLayers=[];const markers=new Map();let filtered=locations,limit=30;
  function showPin(loc){if(!map)return;if($('trails-only').checked){$('trails-only').checked=false;filter();}const marker=markers.get(loc.id);if(marker){map.setView([loc.latitude,loc.longitude],13);marker.openPopup();$('map').scrollIntoView({behavior:'smooth',block:'center'});}}
  function renderCards(){const list=$('locations-list');list.replaceChildren();if(!filtered.length)list.append(node('p','No places match your filters. Try another category or name.','empty'));filtered.slice(0,limit).forEach(l=>list.append(card(l,showPin)));$('load-more').hidden=limit>=filtered.length;}
  function filter(){const query=$('search').value.trim().toLocaleLowerCase(),cat=$('category').value,nto=$('nto').value,only=$('trails-only').checked;filtered=locations.filter(l=>(!query||l.name_bg.toLocaleLowerCase().includes(query))&&(!cat||l.category===cat)&&(!nto||Boolean(l.sto_nto)===(nto==='yes')));limit=30;if(pins){pins.clearLayers();markers.clear();if(!only)filtered.forEach(l=>markers.set(l.id,pin(l,pins)));}$('map-count').textContent=only?'Personal hikes':filtered.length+' places';$('results-title').textContent=filtered.length+' saved places';renderCards();const u=new URL(location.href);['search','category','sto_nto','trails'].forEach(k=>u.searchParams.delete(k));if(query)u.searchParams.set('search',$('search').value);if(cat)u.searchParams.set('category',cat);if(nto)u.searchParams.set('sto_nto',nto);if(only)u.searchParams.set('trails','only');history.replaceState(null,'',u);}
  const params=new URLSearchParams(location.search);$('search').value=params.get('search')||'';$('category').value=params.get('category')||'';$('nto').value=params.get('sto_nto')||'';$('trails-only').checked=params.get('trails')==='only';
  ['search','category','nto','trails-only'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',filter));$('reset-filters').onclick=()=>{['search','category','nto'].forEach(id=>$(id).value='');$('trails-only').checked=false;filter();};$('load-more').onclick=()=>{limit+=30;renderCards();};
  $('fit-map').onclick=()=>{if(!map)return;const b=L.latLngBounds([]);if(!$('trails-only').checked)filtered.forEach(l=>b.extend([l.latitude,l.longitude]));routeLayers.forEach(l=>{if(map.hasLayer(l))b.extend(l.getBounds());});if(b.isValid())map.fitBounds(b.pad(.06),{maxZoom:13});};filter();
  fetch(asset+'data/hikes.geojson').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{
   $('trail-options').replaceChildren();data.features.forEach(f=>{const p=f.properties;const lab=node('label',undefined,'trail-line'),box=document.createElement('input');box.type='checkbox';box.checked=true;box.setAttribute('aria-label','Show '+p.name);const sw=node('span',undefined,'trail-swatch');sw.style.background=p.color;lab.append(box,sw,node('span',p.name));$('trail-options').append(lab,node('p',p.dates+' · '+p.recorded_days+' recorded dates','trail-meta'));
    if(map){const layer=L.geoJSON(f,{style:{color:p.color,weight:3.5,opacity:.9}}).addTo(map);routeLayers.push(layer);const pop=node('div');pop.append(node('h3',p.name),node('p',p.description,'route-note'),node('p',p.source_points.toLocaleString()+' original GPS points · map simplified to 12 m','route-note'));layer.bindPopup(pop);box.onchange=()=>box.checked?layer.addTo(map):map.removeLayer(layer);
     const segments=f.geometry.coordinates;const first=segments[0][0],last=segments[segments.length-1].at(-1);[[first,'Start'],[last,'Finish']].forEach(([c,label])=>{L.circleMarker([c[1],c[0]],{radius:6,color:p.color,fillColor:'#fff',fillOpacity:1,weight:3}).bindTooltip(p.name+' · '+label).addTo(layer);});
    }
   });$('map-status').textContent='Your recorded GPX routes. Recording gaps are kept separate.';
  }).catch(()=>{$('trail-options').replaceChildren(node('p','Your hike tracks could not load. Reload the page.','small'));});
 }
 if(body.dataset.page==='city'){
  let cities=[],nearMap=null,nearLayer=null;const form=$('city-form');
  function showResults(center,results,radius){$('nearby-section').hidden=false;$('city-start').hidden=true;$('nearby-title').textContent=results.length+' places near '+center.name;const container=$('nearby-results');container.replaceChildren();if(!results.length)container.append(node('p','No saved places within this radius. Try a larger area.','empty'));results.forEach(l=>container.append(card(l)));if(!nearMap)nearMap=makeMap('nearby-map');if(nearMap){if(nearLayer)nearMap.removeLayer(nearLayer);nearLayer=L.featureGroup().addTo(nearMap);L.circle([center.lat,center.lon],{radius:radius*1000,color:'#23594a',weight:1,fillOpacity:.05}).addTo(nearLayer);L.circleMarker([center.lat,center.lon],{radius:7,color:'#b15e39',fillOpacity:1}).bindTooltip(center.name+' · search centre').addTo(nearLayer);results.forEach(l=>pin(l,nearLayer));nearMap.invalidateSize();nearMap.fitBounds(nearLayer.getBounds().pad(.05));}}
  const initial=read('nearby-data');if(initial?.center&&initial.results)showResults(initial.center,initial.results,Number(initial.km));
  function error(message){$('city-error').hidden=false;$('city-error').textContent=message;$('nearby-section').hidden=true;$('city-start').hidden=false;}
  function search(event){event?.preventDefault();$('city-error').hidden=true;$('city-choices').replaceChildren();const q=normalize($('city').value),radius=Number($('km').value);if(!q||!Number.isFinite(radius)||radius<1||radius>500){error('Enter a city and a radius from 1 to 500 km.');return;}let matches=cities.filter(c=>c.keys.includes(q));const chosen=matches.find(c=>String(c.id)===$('city-id').value);if(chosen)matches=[chosen];if(!matches.length){error('City not found. Try its Bulgarian or Latin name, or choose a suggestion.');return;}if(matches.length>1){error('More than one settlement has this name. Choose your starting point:');matches.forEach(c=>{const b=node('button',c.name+' · '+c.region+' · '+c.lat+', '+c.lon,'choice');b.type='button';b.onclick=()=>{$('city-id').value=c.id;search();};$('city-choices').append(b);});return;}
   const center=matches[0];$('city-id').value=center.id;const results=locations.map(l=>({...l,distance_km:distance(center,l)})).filter(l=>l.distance_km<=radius).sort((a,b)=>a.distance_km-b.distance_km);showResults(center,results,radius);const u=new URL(location.href);u.search='';u.searchParams.set('city',$('city').value);u.searchParams.set('km',radius);u.searchParams.set('city_id',center.id);history.replaceState(null,'',u);
  }
  $('city').addEventListener('input',()=>{$('city-id').value='';if(!cities.length)return;const q=normalize($('city').value);const list=$('city-suggestions');list.replaceChildren();if(q.length<2)return;cities.filter(c=>c.keys.some(k=>k.startsWith(q))).slice(0,15).forEach(c=>{const o=document.createElement('option');o.value=c.name;o.label=c.region;list.append(o);});});
  if(isStatic){form.querySelector('button').disabled=true;form.addEventListener('submit',search);}
  fetch(asset+'data/cities.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{cities=data;form.querySelector('button').disabled=false;if(isStatic){const q=new URLSearchParams(location.search);$('city').value=q.get('city')||'';$('km').value=q.get('km')||'30';$('city-id').value=q.get('city_id')||'';if(q.has('city'))search();}}).catch(()=>{if(isStatic){form.querySelector('button').disabled=true;error('City data could not load. Please reload the page.');}});
 }
 if(body.dataset.page==='add'){
  const map=makeMap('add-map');let marker=null;const input=$('coordinates');if(map&&input){function update(lat,lon){if(marker)marker.setLatLng([lat,lon]);else marker=L.marker([lat,lon]).addTo(map);}map.on('click',e=>{input.value=e.latlng.lat.toFixed(6)+', '+e.latlng.lng.toFixed(6);update(e.latlng.lat,e.latlng.lng);});input.addEventListener('change',()=>{const parts=input.value.split(',').map(Number);if(parts.length===2&&parts.every(Number.isFinite)&&Math.abs(parts[0])<=90&&Math.abs(parts[1])<=180){update(...parts);map.setView(parts,12);}});if(input.value)input.dispatchEvent(new Event('change'));}
  $('add-form')?.addEventListener('submit',e=>{if(e.target.checkValidity()){const b=e.target.querySelector('button[type=submit]');b.disabled=true;b.textContent='Saving your place…';}});
 }
 if(body.dataset.page==='hall'){
  const dialog=$('diploma-dialog');document.querySelectorAll('.diploma').forEach(b=>b.onclick=()=>{$('dialog-title').textContent=b.dataset.title;$('dialog-image').src=b.dataset.src;$('dialog-image').alt=b.dataset.title;dialog.showModal();});$('close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
 }
})();
